 en:{share:'Share this step',step:'Step link',operation:'Include the 3D action',link:'Share link',copy:'Copy link',copied:'Link copied',manual:'Select the link and copy it.',close:'Close',native:'Share with another app',privacy:'The recipient’s progress and completed checks stay unchanged.'},
 cs:{share:'Sdílet tento krok',step:'Odkaz na krok',operation:'Včetně dílčí 3D operace',link:'Odkaz ke sdílení',copy:'Kopírovat odkaz',copied:'Odkaz zkopírován',manual:'Vyberte a zkopírujte odkaz.',close:'Zavřít',native:'Sdílet v jiné aplikaci',privacy:'Postup a potvrzené kroky příjemce se nezmění.'},
